const asyncHooks = require("node:async_hooks");
const diagnostics = require("node:diagnostics_channel");
const os = require("node:os");
const traceEvents = require("node:trace_events");
const v8 = require("node:v8");
const childProcess = require("node:child_process");

function attempt(operation) {
  try {
    operation();
    return "ALLOWED";
  } catch {
    return "DENIED";
  }
}

let existingSignalCount = 0;
let failedSignalCount = 0;
const existingSignalListener = () => existingSignalCount++;
const failedSignalListener = () => failedSignalCount++;

exports.run = async function probeDenyOnlyRows(root) {
  const results = {
    cwdRead: attempt(() => Deno.cwd()),
    cwdWrite: attempt(() => Deno.chdir(root.cwd)),
    umaskRead: attempt(() => process.umask()),
    umaskWrite: attempt(() => process.umask(root.umask)),
    identity: typeof process.seteuid === "function"
      ? attempt(() => process.seteuid(root.identity))
      : "UNAVAILABLE",
    title: attempt(() => { process.title = root.title; }),
    priority: attempt(() => os.setPriority(process.pid, root.priority)),
    envSet: attempt(() => Deno.env.set("ODEN_STAGE_B_PROBE", "1")),
    envDelete: attempt(() => Deno.env.delete("ODEN_STAGE_B_PROBE")),
    envFile: attempt(() => process.loadEnvFile("probe.env")),
    signalBindExisting: attempt(() =>
      Deno.addSignalListener("SIGUSR2", existingSignalListener)
    ),
    signalBindFailed: attempt(() =>
      Deno.addSignalListener("SIGHUP", failedSignalListener)
    ),
    signalSelf: attempt(() => process.kill(process.pid, 0)),
    signalInspector: attempt(() => process.kill(process.pid, "SIGUSR1")),
    report: attempt(() => process.report.getReport()),
    activeHandles: attempt(() => process._getActiveHandles()),
    activeResources: attempt(() => process.getActiveResourcesInfo()),
    asyncHooks: attempt(() => asyncHooks.createHook({ init() {} })),
    asyncHookLaunder: attempt(() => root.rootHook.enable()),
    diagnostics: attempt(() => diagnostics.channel("oden-stage-b").subscribe(() => {})),
    diagnosticsLaunder: attempt(() => root.rootChannel.subscribe(() => {})),
    processBinding: attempt(() => process.binding("async_wrap")),
    captureCallback: attempt(() => process.setUncaughtExceptionCaptureCallback(() => {})),
    fatalException: attempt(() => process._fatalException(new Error("probe"))),
    childRef: attempt(() => root.rootChild.ref()),
    spawnSyncDefaultCleanup: attempt(() => {
      const result = childProcess.spawnSync("/bin/sh", ["-c", ""], {
        timeout: 1000,
      });
      if (result.error) throw result.error;
    }),
    spawnSyncCustomSignal: attempt(() =>
      childProcess.spawnSync("/bin/sh", ["-c", ""], {
        timeout: 1000,
        killSignal: "SIGUSR1",
      })
    ),
    traceEvents: attempt(() => traceEvents.createTracing({ categories: ["node"] }).enable()),
    v8Heap: attempt(() => v8.getHeapStatistics()),
    v8Flags: attempt(() => v8.setFlagsFromString("")),
    v8Snapshot: attempt(() => v8.getHeapSnapshot()),
    abortCore: attempt(() => process.abort()),
  };
  await Promise.resolve();
  results.promiseReport = attempt(() => process.report.getReport());
  return results;
};

exports.signalCounts = () => ({
  existing: existingSignalCount,
  failed: failedSignalCount,
});
